# Input optimizations - reduce latency
input type:keyboard {
  repeat_delay 200
  repeat_rate 40
}

# Lid switch handling — lock, then screen power off/on.
# Close powers off immediately (nobody sees the panel) and locks via
# logind's Lock signal, which swaypplet-idle serves. Suspend usually
# follows (logind HandleLidSwitch), but inside logind's 30 s holdoff
# after a resume a lid close does NOT suspend — without this lock the
# desktop sat unlocked behind a dark panel. Open powers on directly:
# once the compositor holds the session lock it never renders session
# content, so the only exposure is a close→open flip faster than the
# locker's ~1 s startup. --locked keeps both working under the locker.
bindswitch --locked lid:on exec 'swaymsg -q "output * power off"; loginctl lock-session'
bindswitch --locked lid:off output * power on

# Escape hatch for a stuck-black panel after wake: force every output's
# DPMS back on and restore brightness. --locked so it fires even while
# the locker holds the input inhibitor. Recovers without a reboot when a
# starved compositor wakes with DPMS on but the panel not repainting
# (see black-screen-after-lock, boot 2026-06-04).
bindsym --locked Mod4+Shift+o exec '/nix/store/7x8zgzbdd4jcgr84vcqda0j61j1y4pq5-swayfx-0.6/bin/swaymsg "output * power on" && /nix/store/jr77al427m331cpk0l67z28l5cwv9pj5-brightnessctl-0.5.1/bin/brightnessctl set 100% -n'
